	private async handleMemberAdd(client: ModuleClient, member: GuildMember, bot_id: string): Promise<void> {
		// Los bots SÍ reciben bienvenida DE CANAL: un guild que anuncia quién
		// entra quiere ver también lo que entra automatizado. Lo que no tiene
		// sentido para una cuenta de bot se apaga aquí, y solo aquí:
		//  - DM: Discord no deja abrir un privado con un bot, el envío muere;
		//  - captcha (botón + ghost ping): no hay nadie que lo pulse;
		//  - join_roles: un bot recibe sus permisos por el rol de integración
		//    que le da quien lo invita, no por esta vía.
		const isBot = member.user?.isBot ?? false;

		const loaded = await this.loadGreeterState(client, member.guild_id, bot_id);
		if (!loaded) return;

		const greeter = loaded.config;

		if (!isBot) {
			// La restauración de sticky roles corre SIEMPRE antes que join_roles,
			// bajo la MISMA guarda de bots: si un bot no recibe roles de
			// bienvenida tampoco tiene sentido devolverle los que tuviera de una
			// salida anterior.
			await this.restoreStickyRoles(client, member, greeter, bot_id);
			await this.assignJoinRoles(client, member, greeter, bot_id);
		}

		// Bienvenida, DM y verificación son TRES cosas independientes: el
		// dashboard las expone como interruptores separados y cada una tiene su
		// destino. Salir aquí por `welcome.enabled` dejaba muerto también el
		// captcha de los guilds que solo verifican —sin ghost ping, la única
		// señal que arrastra al nuevo miembro hasta el canal de verificación—.
		//
		// El DM tampoco cuelga de `welcome.enabled`: «saludar en un canal» y
		// «saludar por privado» son decisiones distintas, y colgarlo obligaba a
		// dejar encendido un mensaje de canal que el guild no quería para poder
		// mandar solo el privado.
		const { welcome } = greeter;
		const welcomeEnabled = welcome.enabled;
		const channelId = welcomeEnabled ? welcome.channel_id : null;
		const dmEnabled = !isBot && (welcome.dm?.enabled ?? false);

		// El `language` del guild manda en la UI de captcha (?lang=). Si falla,
		// dejamos sin lang y la web cae a Accept-Language → fallback. No
		// bloqueamos ni el welcome ni la verificación por esto.
		const guildLanguage = isBot ? null : await this.loadGuildLanguage(client, member.guild_id, bot_id);

		const captchaRow = isBot ? null : this.buildCaptchaRow(client, member, greeter, bot_id, guildLanguage);

		// El mensaje de verificación del canal dedicado es PERMANENTE: lo publica
		// el dashboard (`POST /api/guilds/:guild_id/captcha/send`) con la config
		// guardada, y se queda ahí para todo el que entre. El bot NO lo reemite en
		// cada join — hacerlo llenaba el canal de copias idénticas, una por
		// miembro. Aquí el canal dedicado solo decide dos cosas: que el botón no
		// se pegue al welcome, y a dónde apunta el ghost ping.
		const captchaChannelId = greeter.captcha?.channel_id ?? null;
		const captchaInOwnChannel = Boolean(captchaRow && captchaChannelId);

		// Sin destino de welcome (canal ni DM) y sin canal dedicado de
		// verificación no hay nada que hacer con este join. Ojo: con el welcome
		// apagado y captcha SIN canal propio el botón tampoco tiene dónde ir,
		// porque solo viaja pegado al mensaje de bienvenida.
		if (!channelId && !dmEnabled && !captchaInOwnChannel) {
			client.logger.warn(
				LogType.DISCORD,
				`[guildMemberAdd] no target configured guild_id=${member.guild_id} bot_id=${bot_id}`
			);
			return;
		}

		const displayName = member.displayName ?? member.user?.username ?? "New Member";
		const memberMention = member.id ? `<@${member.id}>` : displayName;

		// Canal donde el nuevo miembro encuentra el enlace de verificación. Es lo
		// que mira el ghost ping: pingar un canal sin nada que leer solo molesta.
		// Con canal dedicado el mensaje permanente ya está publicado allí.
		let verificationChannelId: string | null = captchaInOwnChannel ? captchaChannelId : null;

		if (channelId || dmEnabled) {
			// El fetch del guild y el contador de miembros solo alimentan las
			// plantillas del welcome (`{guild_name}`, `{member_count}`). Un guild
			// que únicamente verifica no los paga en cada join.
