	async removeVoiceState(guildId: string, userId: string): Promise<void> {
		const prev = await this.getVoiceState(guildId, userId);
		if (prev?.channel_id) {
			await this.srem(this.voiceChannelMembersKey(guildId, prev.channel_id), userId);
		}
		await this.del(this.voiceStateKey(guildId, userId));
		// Auditoría 2.4: tiramos también el hash voiceServer. La ruta de salida
		// solía conservar las credenciales del servidor; si el bot volvía a entrar,
		// el camino rápido de Connection.ts sintetizaba un SESSION_READY con la
		// sesión muerta y Lavalink daba 4006. El TTL de 60 s de setVoiceServer es
		// un backstop, pero borrarlo explícitamente al salir cierra la ventana al
		// instante.
		await this.removeVoiceServer(guildId, userId);
	}
```

