export class TempVoiceChannelCache extends BaseCache {
	private buildChannelKey(channelId: string): string {
		return `tempvoice-module:channel:${channelId}`;
	}

	private buildGuildKey(botId: string, guildId: string): string {
		return `tempvoice-module:guild:${botId}:${guildId}`;
	}

	private buildUserKey(botId: string, guildId: string, userId: string): string {
		return `tempvoice-module:userchan:${botId}:${guildId}:${userId}`;
	}

	private buildCreateLockKey(botId: string, guildId: string, userId: string): string {
		return `tempvoice-module:createlock:${botId}:${guildId}:${userId}`;
	}

	private buildRenameQuotaKey(channelId: string): string {
		return `tempvoice-module:rename:${channelId}`;
	}

	private buildCreateQuotaKey(botId: string, guildId: string): string {
		return `tempvoice-module:createquota:${botId}:${guildId}`;
	}

	/**
	 * Contador de ventana FIJA compartido por las cuotas de este cache.
	 *
	 * Ventana fija (no deslizante) a propósito: la clave sólo recibe TTL en el primer
	 * incremento, así que reintentar dentro de la ventana no la alarga y el `TTL` que
	 * devolvemos es literalmente "cuánto falta para que se reabra".
	 */
	private async consumeFixedWindow(
		key: string,
		max: number,
		windowSeconds: number
	): Promise<{ allowed: boolean; retryAfterSeconds: number }> {
		const count = Number(await this.call("INCR", key));

		if (count === 1) {
			await this.expire(key, windowSeconds);
			return { allowed: true, retryAfterSeconds: 0 };
		}

		const ttl = Number(await this.call("TTL", key));
		// `-1` = clave sin TTL (falló el EXPIRE del primer incremento). Se lo ponemos
