function validateActionList(
	actions: DBAutomation["actions"] | undefined,
	provided: Set<AutomationContextKey>,
	pathPrefix: string
): AutomationIssue[] {
	const issues: AutomationIssue[] = [];
	actions?.forEach((action, index) => {
		const at = `${pathPrefix}[${index}]`;
		if (!isAutomationActionType(action.type)) {
			issues.push({ path: `${at}.type`, code: "unknown_action", message: "Esa acción no existe." });
			return;
		}
		const def = AUTOMATION_ACTIONS[action.type];
		const missing = def.requires.filter((k) => !provided.has(k));
		if (missing.length > 0) {
			issues.push({
				path: `${at}.type`,
				code: "context_missing",
				message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`
			});
		}
		issues.push(...validateParams(action.params, def.params, `${at}.params`));
	});
	return issues;
}
```

