export async function countOnlineMembers(
	client: ModuleClient,
	botId: string,
	guildId: string,
	roleIds: string[]
): Promise<number | null> {
	try {
		const onlineIds = await onlineMembers(client.automationRedis, botId, guildId);
		if (onlineIds === null || onlineIds.length === 0) return null;
		if (roleIds.length === 0) return onlineIds.length;

		const wanted = new Set(roleIds);
		const matches = await Promise.all(
			onlineIds.map(async (memberId) => {
				const roles = await client.redisAdapter.cache.core.guild.getGuildMemberRoles(guildId, memberId);
				return roles.some((roleId) => wanted.has(roleId));
			})
		);
		return matches.filter(Boolean).length;
	} catch {
		return null;
	}
}
```

