func scopeExpr(scope, voiceMetric, alias string) string {
	prefix := ""
	if alias != "" {
		prefix = alias + "."
	}
	switch scope {
	case dbleveling.ScopeText:
		return prefix + "text_xp"
	case dbleveling.ScopeVoice:
		if voiceMetric == dbleveling.VoiceMetricTime {
			return prefix + "voice_seconds"
		}
		return prefix + "voice_xp"
	default: // ScopeUnified y cualquier otro valor no reconocido.
		return "(" + prefix + "text_xp + " + prefix + "voice_xp)"
	}
}
