func (b *BotCoreCache) IsBotOnline(ctx context.Context, botID string) (bool, error) {
	clusterIDs, err := b.resolveClusterIds(ctx, botID)
	if err != nil {
		return false, err
	}
	for _, cid := range clusterIDs {
		alive, existsErr := b.client.Exists(ctx, coreClusterAliveKey(botID, cid))
		if existsErr != nil {
			return false, existsErr
		}
		if alive {
			return true, nil
		}
	}
	return false, nil
}
