async function execute(
	rawAction: DBAutomationAction,
	ctx: AutomationContext,
	budget: ExecutionBudget,
	deps: RunnerDeps
	// El `code` se propaga —y no se descarta como antes— porque es lo que
	// distingue un fallo transitorio de uno definitivo: sin él, `PERMISSION_DENIED`
	// se reintentaría dos veces para volver a fallar igual.
): Promise<{ ok: boolean; message?: string; code?: string }> {
	const { client, redis } = deps;
	// Las variables se resuelven UNA vez, aquí, sobre una copia. Los ejecutores
	// de abajo leen texto ya listo y no vuelven a tocar el contexto.
	const p = resolveParamVariables(rawAction.params ?? {}, ctx);

	switch (rawAction.type) {
		// ─── Mensajería ─────────────────────────────────────────────────────────

		case "send_message": {
			// El FORMATO manda, igual que en el mensaje de bienvenida. Ausente se lee
			// como "plain": las automatizaciones guardadas antes de existir el campo
			// hacían exactamente eso.
			const mode = str(p, "mode") || "plain";
			const wantsEmbed = mode === "embed" || mode === "embed_image";
			const wantsImage = mode === "image" || mode === "embed_image";
			// El lienzo avanzado gana si el modo lo pide y hay algo que pintar; si no
			// (modo básico, sin canvas, o el render falló) cae al `image_url` de
			// siempre — mismo comportamiento que antes de que existiera el avanzado.
			const canvasImage = wantsImage ? await renderAdvancedImage(p, ctx) : null;
			const imageUrl = wantsImage && !canvasImage ? str(p, "image_url") : "";

			const res = await discord.sendMessage(client, {
				botId: ctx.botId,
				guildId: ctx.guildId,
				channelId: str(p, "channel"),
				// En «texto + imagen» la URL viaja EN EL CONTENIDO: sin embed, la única
				// forma de que Discord la muestre es que el enlace esté en el texto. Con
				// el lienzo avanzado no hace falta: el adjunto ya se ve solo.
				content:
					wantsImage && !wantsEmbed && !canvasImage
						? `${str(p, "content")}\n${imageUrl}`.trim()
						: str(p, "content"),
				...(wantsEmbed
					? {
							embed: {
								title: str(p, "embed_title") || undefined,
								description: str(p, "embed_description") || undefined,
								color: parseColor(str(p, "embed_color")),
								// Y aquí va como `image` del embed, que es donde Discord la
								// pinta grande en vez de como enlace suelto. Con lienzo
								// avanzado apunta al adjunto en vez de a la URL básica.
								imageUrl: canvasImage ? `attachment://${CANVAS_ATTACHMENT_NAME}` : imageUrl || undefined
							}
						}
					: {}),
				...(canvasImage
					? { files: [{ name: CANVAS_ATTACHMENT_NAME, data: canvasImage, contentType: "image/jpeg" }] }
					: {})
			});
			scheduleDelete(deps, ctx, str(p, "channel"), res.data, num(p, "delete_after"));

			// El autopublicado va DESPUÉS y sólo si el envío salió: sin id de mensaje
			// no hay nada que publicar. Su fallo SÍ tumba la acción —quien marca la
			// casilla espera que se publique—, y no puede duplicar nada porque
			// `send_message` no es reintentable.
			if (bool(p, "crosspost") && res.ok) {
				const messageId = sentMessageId(res.data);
				if (messageId) {
					const published = await discord.crosspostMessage(client, ctx.guildId, str(p, "channel"), messageId);
					if (!published.ok) return { ok: false, message: `Mensaje enviado, pero no se pudo autopublicar: ${published.message}` };
				}
			}

			return res;
		}

		case "send_dm": {
			// Mismo criterio que `send_message`, incluido que la imagen viaje en el
			// texto cuando no hay embed: fuera de él Discord no la pinta de otra forma.
			const mode = str(p, "mode") || "plain";
			const wantsEmbed = mode === "embed" || mode === "embed_image";
