async function repostSticky(
	deps: RunnerDeps,
	ctx: AutomationContext,
	channelId: string,
	base: string,
	p: Record<string, unknown>
): Promise<void> {
	const { client, redis } = deps;
	try {
		const wantsEmbed = (str(p, "mode") || "plain") === "embed";

		const res = await discord.sendMessage(client, {
			botId: ctx.botId,
			guildId: ctx.guildId,
			channelId,
			content: str(p, "content"),
			...(wantsEmbed
				? {
						embed: {
							title: str(p, "embed_title") || undefined,
							description: str(p, "embed_description") || undefined,
							color: parseColor(str(p, "embed_color"))
						}
					}
				: {})
		});

		const messageId = sentMessageId(res.data);
		if (!res.ok || !messageId) {
			// Se suelta el lock para que el próximo mensaje del canal reintente en
			// vez de esperar a que caduque.
			await releaseSticky(redis, base);
			logger.warn(LogType.ENGINE, `[${ctx.guildId}] sticky en ${channelId}: no se pudo publicar (${res.message})`);
			return;
		}

		const previous = await readStickyMessageId(redis, base);
		// El id nuevo se guarda ANTES de borrar el viejo: si el borrado falla, lo
		// peor que pasa es un mensaje de más en el canal. Al revés, un fallo entre
		// borrar y guardar dejaría el sticky nuevo sin registrar y el siguiente
		// ciclo no lo borraría nunca.
		await commitSticky(redis, base, messageId);

		if (previous && previous !== messageId) {
			await discord.deleteMessage(client, ctx.guildId, channelId, previous);
		}
	} catch (err) {
		await releaseSticky(redis, base).catch(() => {
			/* Redis caído: el TTL del lock lo suelta solo */
		});
		logger.error(LogType.ENGINE, `[${ctx.guildId}] sticky en ${channelId} lanzó:`, err as Error);
	}
}
