	// ─── Estadísticas ───────────────────────────────────────────────────────
	// Mismo trato que `counter_set`: no tocan Discord, sólo leen un número y
	// lo dejan en `ctx.vars` para que las acciones de detrás lo usen en sus
	// campos de texto.

	case "count_voice_members": {
		const channelId = str(p, "channel");
		const count = channelId
			? await countVoiceMembers(client, ctx.guildId, channelId)
			: await countGuildVoiceMembers(client, ctx.guildId);
		return writeStatVar(ctx, str(p, "save_as"), count);
	}

	case "count_members":
		return writeStatVar(ctx, str(p, "save_as"), ctx.guild.memberCount);

	case "count_role_members": {
		const roles = list(p, "roles");
		if (roles.length === 0) return writeStatVar(ctx, str(p, "save_as"), null);

		const count =
			str(p, "scope") === "voice"
				? await countVoiceMembersWithRoles(client, ctx.guildId, roles)
				: await countGuildMembersWithRoles(client, ctx.guildId, roles);
		return writeStatVar(ctx, str(p, "save_as"), count);
	}

	// Sin roles cuenta a TODOS los conectados; con roles, sólo a quien lleve
	// alguno. Es el único contador cuyo filtro de roles es opcional: «cuánta
	// gente hay en línea» es una pregunta completa por sí sola.
	case "count_online_members":
		return writeStatVar(
			ctx,
			str(p, "save_as"),
			await countOnlineMembers(client, ctx.botId, ctx.guildId, list(p, "roles"))
		);

	case "run_automation":
		await deps.runNested(str(p, "automation"), ctx, budget);
		return { ok: true };

	default:
		return { ok: false, message: "Acción no implementada" };
}

import type { AutomationActionDef, AutomationActionType, AutomationParam } from "./types.js";

/**
 * Catálogo de ACCIONES.
 *
 * Todas tienen transporte gRPC en el gateway hoy — está comprobado contra los
 * `.proto`, no supuesto. Si añades una acción nueva, comprueba que su RPC existe
 * ANTES de meterla aquí: el catálogo es lo que la dashboard ofrece, y ofrecer una
 * acción sin transporte es prometer algo que falla en silencio en producción.
 */

/** Motivo para el registro de auditoría de Discord. */
const reasonParam: AutomationParam = {
	key: "reason",
	type: "text",
	required: false,
	label: "Motivo",
	hint: "Aparece en el registro de auditoría de Discord.",
	max: 512,
	supportsVariables: true,
	default: ""
