export function getAvailableVariables(trigger: AutomationTriggerType): AutomationVariable[] {
	const provided = new Set<AutomationContextKey>(AUTOMATION_TRIGGERS[trigger].provides);
	return AUTOMATION_VARIABLES.filter((v) => v.requires === null || provided.has(v.requires));
