	// aquí. Tarjeta propia para que se encuentre.
	count_online_members: {
		key: "count_online_members",
		category: "stats",
		label: "Contar miembros conectados",
		description:
			"Cuenta cuánta gente está en línea ahora mismo, en todo el servidor o sólo la que tiene un rol. Necesita el permiso de presencias, y cuenta a quien el bot haya visto conectarse desde que arrancó.",
