import { describe, expect, it } from "vitest";
import { AUTOMATION_ACTIONS, RETRYABLE_ACTIONS } from "./actions.js";
import { AUTOMATION_CONDITIONS } from "./conditions.js";
import { AUTOMATION_REQUIRED_EVENTS, AUTOMATION_TRIGGERS } from "./triggers.js";
import {
	AUTOMATION_ACTION_KEYS,
	AUTOMATION_CONDITION_KEYS,
	AUTOMATION_EXECUTION_MODES,
	AUTOMATION_TRIGGER_KEYS,
	executionModeOf,
	triggersForMode,
	type AutomationParam
} from "./types.js";
import { buildDefaultParams, getAvailableActions, getAvailableConditions, validateParams } from "./validate.js";
import { AUTOMATION_VARIABLES, flowVariables, getAvailableVariables } from "./variables.js";

// El catálogo lo consumen la dashboard Y el módulo, y ninguna de las dos puede
// detectar sola que está mal escrito: la dashboard pinta un control roto y el
// módulo ejecuta lo que le llegue. Estos tests son el único sitio donde una
// entrada mal copiada se cae, así que van sobre la COHERENCIA del catálogo, no
// sobre valores concretos (que cambiarán).

const allParams = (): Array<{ owner: string; param: AutomationParam }> => [
	...Object.values(AUTOMATION_TRIGGERS).flatMap((d) => d.params.map((param) => ({ owner: `trigger:${d.key}`, param }))),
	...Object.values(AUTOMATION_CONDITIONS).flatMap((d) =>
		d.params.map((param) => ({ owner: `condition:${d.key}`, param }))
	),
	...Object.values(AUTOMATION_ACTIONS).flatMap((d) => d.params.map((param) => ({ owner: `action:${d.key}`, param })))
];

describe("coherencia del catálogo", () => {
	it("la clave del Record coincide con el `key` de cada definición", () => {
		// Se rompe copiando y pegando una entrada y olvidando cambiar el `key` de
		// dentro: el módulo busca por la clave del Record y la dashboard enseña la
		// de dentro, así que la interfaz apunta a una acción y se ejecuta otra.
		for (const [key, def] of Object.entries(AUTOMATION_TRIGGERS)) expect(def.key).toBe(key);
		for (const [key, def] of Object.entries(AUTOMATION_CONDITIONS)) expect(def.key).toBe(key);
		for (const [key, def] of Object.entries(AUTOMATION_ACTIONS)) expect(def.key).toBe(key);
	});

	it("están definidas todas las claves declaradas", () => {
		expect(Object.keys(AUTOMATION_TRIGGERS).sort()).toEqual([...AUTOMATION_TRIGGER_KEYS].sort());
		expect(Object.keys(AUTOMATION_CONDITIONS).sort()).toEqual([...AUTOMATION_CONDITION_KEYS].sort());
		expect(Object.keys(AUTOMATION_ACTIONS).sort()).toEqual([...AUTOMATION_ACTION_KEYS].sort());
	});

	it("no hay parámetros repetidos dentro de un mismo bloque", () => {
		const check = (name: string, params: AutomationParam[]) => {
			const keys = params.map((p) => p.key);
			expect(new Set(keys).size, `${name} repite un parámetro`).toBe(keys.length);
		};
		for (const def of Object.values(AUTOMATION_TRIGGERS)) check(`trigger:${def.key}`, def.params);
		for (const def of Object.values(AUTOMATION_CONDITIONS)) check(`condition:${def.key}`, def.params);
		for (const def of Object.values(AUTOMATION_ACTIONS)) check(`action:${def.key}`, def.params);
	});

	it("todo `select` trae opciones y su default es una de ellas", () => {
		for (const { owner, param } of allParams()) {
			if (param.type !== "select") continue;
			expect(param.options?.length, `${owner}.${param.key} no tiene opciones`).toBeGreaterThan(0);
			if (param.default === undefined || param.default === null) continue;
			const values = new Set(param.options?.map((o) => o.value));
			const defaults = Array.isArray(param.default) ? param.default : [param.default];
			for (const value of defaults) {
				expect(values.has(String(value)), `${owner}.${param.key}: el default no está entre las opciones`).toBe(true);
			}
		}
	});

	it("sólo los select llevan `multiple`, y sólo los textos `supportsVariables`", () => {
		for (const { owner, param } of allParams()) {
			if (param.multiple) expect(param.type, `${owner}.${param.key}`).toBe("select");
			if (param.supportsVariables) {
				expect(["text", "long_text"], `${owner}.${param.key}`).toContain(param.type);
			}
		}
	});

	it("todo `pattern` declarado es una expresión regular válida", () => {
		for (const { owner, param } of allParams()) {
			if (!param.pattern) continue;
			expect(() => new RegExp(param.pattern as string), `${owner}.${param.key}`).not.toThrow();
		}
	});

	it("los rangos declarados son coherentes", () => {
		for (const { owner, param } of allParams()) {
			if (param.min !== undefined && param.max !== undefined) {
				expect(param.min, `${owner}.${param.key}`).toBeLessThanOrEqual(param.max);
			}
		}
	});

	it("no hay etiquetas vacías: son el fallback cuando falta la traducción", () => {
		for (const { owner, param } of allParams()) {
			expect(param.label.trim(), `${owner}.${param.key}`).not.toBe("");
		}
		for (const def of [
			...Object.values(AUTOMATION_TRIGGERS),
			...Object.values(AUTOMATION_CONDITIONS),
			...Object.values(AUTOMATION_ACTIONS)
		]) {
			expect(def.label.trim(), def.key).not.toBe("");
			expect(def.description.trim(), def.key).not.toBe("");
		}
	});
});

describe("alcanzabilidad", () => {
	// Un bloque que ningún disparador puede satisfacer sale en el catálogo, no
	// aparece nunca en ningún selector y nadie se entera de que sobra.
	it("toda condición se puede usar con algún disparador", () => {
		for (const key of AUTOMATION_CONDITION_KEYS) {
			const usable = AUTOMATION_TRIGGER_KEYS.some((t) => getAvailableConditions(t).some((c) => c.key === key));
			expect(usable, `la condición ${key} es inalcanzable`).toBe(true);
		}
	});

	it("toda acción se puede usar con algún disparador", () => {
		for (const key of AUTOMATION_ACTION_KEYS) {
			const usable = AUTOMATION_TRIGGER_KEYS.some((t) => getAvailableActions(t).some((a) => a.key === key));
			expect(usable, `la acción ${key} es inalcanzable`).toBe(true);
		}
	});

	it("todo disparador admite al menos una acción", () => {
		for (const key of AUTOMATION_TRIGGER_KEYS) {
			expect(getAvailableActions(key).length, `el disparador ${key} no admite ninguna acción`).toBeGreaterThan(0);
		}
	});

	it("«borrar el mensaje» sólo se ofrece cuando hay mensaje", () => {
		expect(getAvailableActions("message_send").map((a) => a.key)).toContain("delete_message");
		expect(getAvailableActions("member_join").map((a) => a.key)).not.toContain("delete_message");
	});

	it("«dar un rol» no se ofrece cuando no hay miembro", () => {
		expect(getAvailableActions("member_join").map((a) => a.key)).toContain("add_role");
		// Al borrarse un canal no hay nadie a quien darle nada.
		expect(getAvailableActions("channel_delete").map((a) => a.key)).not.toContain("add_role");
	});

	it("«su cuenta tenga cierta antigüedad» nace en «Menos de»", () => {
		// El default importa de verdad: quien añade este bloque quiere filtrar
		// CUENTAS NUEVAS (raids, multicuentas). Con «Más de», quien no tocaba el
		// desplegable publicaba lo contrario de lo que quería y la condición era
		// `false` para siempre, sin ningún error — costó una sesión de diagnóstico.
		const comparison = AUTOMATION_CONDITIONS.account_age.params.find((p) => p.key === "comparison");
		expect(comparison?.default).toBe("less");
	});

	it("las demás condiciones de umbral siguen naciendo en «Más de»", () => {
		// El cambio es SÓLO de antigüedad de cuenta: en «longitud del mensaje» o en
		// un contador, «más de» es lo que la gente busca.
		for (const key of ["message_length", "counter_compare", "member_age"] as const) {
			const comparison = AUTOMATION_CONDITIONS[key].params.find((p) => p.key === "comparison");
			expect(comparison?.default, `${key} cambió de default sin querer`).toBe("more");
		}
	});
});

describe("eventos de Discord", () => {
	it("AUTOMATION_REQUIRED_EVENTS cubre todos los disparadores y no repite", () => {
		// Es lo que se pasa al `events: [...]` del módulo. Un evento que falte deja
		// su handler MUDO, sin error: por eso se deriva y no se escribe a mano.
		const declared = new Set(AUTOMATION_REQUIRED_EVENTS);
		expect(declared.size).toBe(AUTOMATION_REQUIRED_EVENTS.length);
		for (const def of Object.values(AUTOMATION_TRIGGERS)) {
			for (const event of def.events) {
				expect(declared.has(event), `falta el evento de ${def.key}`).toBe(true);
			}
		}
	});

	it("todo disparador declara al menos un evento, salvo los de horario", () => {
		// Un disparador de evento SIN eventos queda mudo: el core no le enruta
		// nada y no hay error que lo delate. Por eso este guard.
		//
		// La excepción es `schedule`, y es la ÚNICA: no lo alimenta Discord sino el
		// poller del módulo (`SchedulePoller`). Declararle un evento haría que el
		// core le mandara tráfico que no sabe atender.
		for (const def of Object.values(AUTOMATION_TRIGGERS)) {
			if (def.category === "schedule") {
				expect(def.events, `${def.key} no debe declarar eventos`).toEqual([]);
				continue;
			}
			expect(def.events.length, def.key).toBeGreaterThan(0);
		}
	});

	it("`member_activity` provee user+member y sus eventos entran en AUTOMATION_REQUIRED_EVENTS", () => {
		// Es el disparador que más eventos junta de golpe (mensajes, reacciones,
		// voz, hilos): el que mejor delata un `events` copiado a medias o uno que
		// se quedó fuera de `AUTOMATION_REQUIRED_EVENTS`.
		const def = AUTOMATION_TRIGGERS.member_activity;
		expect(def.provides).toEqual(["user", "member"]);
		for (const event of def.events) {
			expect(AUTOMATION_REQUIRED_EVENTS, event).toContain(event);
		}
	});
});

describe("variables", () => {
	it("no se ofrece {message} con un disparador que no trae mensaje", () => {
		const tokens = getAvailableVariables("member_join").map((v) => v.token);
		expect(tokens).toContain("{user}");
		expect(tokens).not.toContain("{message}");
	});

	it("las variables sin contexto están siempre", () => {
		const always = AUTOMATION_VARIABLES.filter((v) => v.requires === null).map((v) => v.token);
		for (const key of AUTOMATION_TRIGGER_KEYS) {
			const tokens = getAvailableVariables(key).map((v) => v.token);
			for (const token of always) expect(tokens, key).toContain(token);
		}
	});

	it("no hay tokens repetidos", () => {
		const tokens = AUTOMATION_VARIABLES.map((v) => v.token);
		expect(new Set(tokens).size).toBe(tokens.length);
	});
});

describe("buildDefaultParams", () => {
	const allDefs = () => [
		...Object.values(AUTOMATION_TRIGGERS),
		...Object.values(AUTOMATION_CONDITIONS),
		...Object.values(AUTOMATION_ACTIONS)
	];

	it("ningún valor de fábrica está mal formado", () => {
		// Un default inválido es especialmente traicionero: el bloque nace roto y
		// el usuario ve un error en un campo que no ha tocado nunca.
		//
		// `missing_required` se excluye A PROPÓSITO: un bloque recién añadido con
		// un campo obligatorio DEBE nacer vacío para que el formulario lo pinte y
		// se lo pida. Lo que no puede es nacer con un valor con formato, rango u
		// opción imposibles.
		for (const def of allDefs()) {
			const issues = validateParams(buildDefaultParams(def.params), def.params, "params").filter(
				(i) => i.code !== "missing_required"
			);
			expect(issues, `${def.key}: ${JSON.stringify(issues)}`).toEqual([]);
		}
	});

	it("sólo quedan sin rellenar los obligatorios que no declaran default", () => {
		// El complemento del test anterior: sin esto, un default mal escrito que
		// dejase el campo vacío se colaría disfrazado de «obligatorio sin default».
		for (const def of allDefs()) {
			const params = buildDefaultParams(def.params);
			const missing = validateParams(params, def.params, "params")
				.filter((i) => i.code === "missing_required")
				.map((i) => i.path.replace("params.", ""));
			for (const key of missing) {
				const param = def.params.find((p) => p.key === key);
				expect(param?.required, `${def.key}.${key}`).toBe(true);
				expect(param?.default, `${def.key}.${key} declara un default que no rellena nada`).toBeUndefined();
			}
		}
	});
});

describe("modo de ejecución", () => {
	it("executionModeOf deriva los tres modos por la clave del disparador", () => {
		expect(executionModeOf("on_interval")).toBe("interval");
		expect(executionModeOf("on_schedule")).toBe("schedule");
		expect(executionModeOf("member_join")).toBe("always");
	});

	it("triggersForMode con el modo `interval` devuelve exactamente on_interval", () => {
		expect(triggersForMode("interval").map((t) => t.key)).toEqual(["on_interval"]);
	});

	it("triggersForMode con el modo `always` deja fuera los de horario y trae los de estadística", () => {
		const keys = triggersForMode("always").map((t) => t.key);
		expect(keys).not.toContain("on_interval");
		expect(keys).not.toContain("on_schedule");
		expect(keys).toContain("member_count_changed");
		expect(keys).toContain("voice_count_changed");
	});

	it("los tres modos reparten el catálogo entero, sin huecos ni duplicados", () => {
		const byMode = AUTOMATION_EXECUTION_MODES.flatMap((mode) => triggersForMode(mode));
		expect(byMode.map((t) => t.key).sort()).toEqual([...AUTOMATION_TRIGGER_KEYS].sort());
	});
});

